const rows = $input.all();

const report = {
  totalApplications: rows.length,
  shortlisted: 0,
  approved: 0,
  rejected: 0,
  interviewScheduled: 0,
  offerLettersSent: 0
};

for (const row of rows) {

  // Read values safely
  const recommendation = (row.json.Recommendation || row.json.recommendation || "").trim();
  const status = (row.json.Status || row.json.status || "").trim();
  const interviewDate = (row.json["Interview Date"] || "").toString().trim();
  const offerLetter = (row.json["Offer Letter Sent"] || "").toString().trim().toLowerCase();

  // AI Shortlisted
  if (recommendation === "Shortlisted") {
    report.shortlisted++;
  }

  // HR Approved (Count Hired as Approved)
  if (status === "Hired") {
    report.approved++;
  }

  // Rejected
  if (status === "Rejected") {
    report.rejected++;
  }

  // Interview Scheduled
  if (interviewDate !== "") {
    report.interviewScheduled++;
  }

  // Offer Letter Sent
  if (offerLetter === "yes") {
    report.offerLettersSent++;
  }
}

return [
  {
    json: {
      "Total Applications": report.totalApplications,
      "AI Shortlisted": report.shortlisted,
      "HR Approved": report.approved,
      "Rejected": report.rejected,
      "Interview Scheduled": report.interviewScheduled,
      "Offer Letters Sent": report.offerLettersSent
    }
  }
];
